name.source:
def f():
    for x in values:
        yield x

tuple.source:
def f():
    for x, y in values:
        yield x, y

nested-tuple.source:
def f():
    for x, (y, z) in values:
        yield x, (y, z)

else.source:
def f():
    for x in values:
        yield x
    else:
        pass

multiple-body.source:
def f():
    for x in values:
        work()
        yield x

changed-value.source:
def f():
    for x in values:
        yield x + 1

different-name.source:
def f():
    for x in values:
        yield y

async-function.source:
async def f():
    for x in values:
        yield x

external-use.source:
def f():
    for x in values:
        yield x
    use(x)

only-yield-use.source:
def f():
    for x in values:
        yield x

noqa.source:
def f():
    for x in values:
        yield x  # noqa: UP028

file-noqa.source:
# ruff: noqa: UP028
def f():
    for x in values:
        yield x

multiline.source:
def f():
    for x, y in values:
        yield (x, y)

with-parentheses.source:
def f():
    for x in values:
        yield (x)

list-target.source:
def f():
    for [x, y] in values:
        yield [x, y]

nested-sync-function-in-async.source:
async def outer():
    def inner():
        for x in values:
            yield x
